"""Greedy paragraph wrapping."""
import re


def wrap(text, width):
    if width < 1:
        raise ValueError(f"width must be at least 1: {width}")
    out = []
    for para in re.split(r"\n[ \t\r\f\v]*(?:\n[ \t\r\f\v]*)*", "\n" + text):
        words = para.split()
        if not words:
            continue
        line = words[0]
        lines = []
        for w in words[1:]:
            if len(line) + 1 + len(w) <= width:
                line += " " + w
            else:
                lines.append(line)
                line = w
        lines.append(line)
        out.append("\n".join(lines))
    return "\n\n".join(out)
